def run_simulation(machines_config):
    import heapq

    machine_ids = ['M01', 'M02', 'M03', 'M04', 'M05', 'M06', 'M07', 'M08']

    # Machine state
    machine_up = {m: True for m in machine_ids}
    machine_avail_cpu = {m: machines_config[m]['cpu'] for m in machine_ids}
    machine_avail_mem = {m: machines_config[m]['mem'] for m in machine_ids}
    machine_tasks = {m: [] for m in machine_ids}  # list of (task_id, end_time)

    # Queue of waiting tasks
    queue = []

    # Track first start times
    first_start = {}

    # Collect all initial time points
    time_points = set()
    for time in submissions_by_time:
        time_points.add(time)
    for m in machine_ids:
        if machines_config[m]['fails_at'] is not None:
            time_points.add(machines_config[m]['fails_at'])
        if machines_config[m]['returns_at'] is not None and machines_config[m]['returns_at'] <= 1200:
            time_points.add(machines_config[m]['returns_at'])

    time_heap = list(time_points)
    heapq.heapify(time_heap)

    while time_heap:
        t = heapq.heappop(time_heap)

        if t > 1200:
            break

        # Step 1: Finishes
        for m in machine_ids:
            still_running = []
            for (task_id, end_time) in machine_tasks[m]:
                if end_time == t:
                    task_info = tasks[task_id]
                    machine_avail_cpu[m] += task_info['cpu']
                    machine_avail_mem[m] += task_info['mem']
                else:
                    still_running.append((task_id, end_time))
            machine_tasks[m] = still_running

        # Step 2: Failures
        for m in machine_ids:
            if machines_config[m]['fails_at'] == t:
                machine_up[m] = False
                for (task_id, end_time) in machine_tasks[m]:
                    queue.append(task_id)
                machine_tasks[m] = []
                machine_avail_cpu[m] = 0
                machine_avail_mem[m] = 0

        # Step 3: Returns
        for m in machine_ids:
            if machines_config[m]['returns_at'] == t:
                machine_up[m] = True
